// FILTER: 조건(col_idx > 0)을 만족하는 행만 유지
func executor_exec_filter(ex: *Executor, t: schema.Table, col_idx: i32) -> i32 {
    if col_idx < 0 || col_idx >= t.schema.col_count {
        return EXEC_ERR_INVALID_OP;
    }

    let new_count = 0;
    let i = 0;

    // 각 행에 대해 필터 조건 적용
    for i = 0; i < ex.row_buf.count; i = i + 1 {
        let row_idx = ex.row_buf.row_indices[i];

        // 컬럼 값 추출 (정수 컬럼으로 가정)
        let col_val = t.int_cols[col_idx * schema.MAX_ROWS + row_idx];

        // > 0 조건 필터
        if col_val > 0 {
            ex.row_buf.row_indices[new_count] = row_idx;
            new_count = new_count + 1;
        }
    }

    ex.row_buf.count = new_count;
    return EXEC_OK;
}

