func executor_exec_sort(ex: *Executor, t: schema.Table, sort_col: i32) -> i32 {
    if sort_col < 0 || sort_col >= t.schema.col_count {
        return EXEC_ERR_INVALID_OP;
    }

    // Knuth 갭 시퀀스: 364, 121, 40, 13, 4, 1
    let gaps = make([i32], 6);
    gaps[0] = 364;
    gaps[1] = 121;
    gaps[2] = 40;
    gaps[3] = 13;
    gaps[4] = 4;
    gaps[5] = 1;

    let g_idx = 0;
    let gap = 0;
    let i = 0;
    let j = 0;

    // 각 갭에 대해 쉘 정렬 실행
    for g_idx = 0; g_idx < 6; g_idx = g_idx + 1 {
        gap = gaps[g_idx];

        // 갭이 행 버퍼 크기를 초과하면 건너뛰기
        if gap > ex.row_buf.count {
            continue;
        }

        // 갭 삽입 정렬
        for i = gap; i < ex.row_buf.count; i = i + 1 {
            let key_idx = ex.row_buf.row_indices[i];
            let key_val = t.int_cols[sort_col * schema.MAX_ROWS + key_idx];

            j = i - gap;

            // 갭 거리로 비교하며 역순 이동
            for j >= 0 {
                let curr_row_idx = ex.row_buf.row_indices[j];
                let curr_val = t.int_cols[sort_col * schema.MAX_ROWS + curr_row_idx];

                if curr_val <= key_val {
                    break;
                }

                // 갭 거리만큼 뒤로 이동
                ex.row_buf.row_indices[j + gap] = ex.row_buf.row_indices[j];
                j = j - gap;
            }

            // 올바른 위치에 삽입
            ex.row_buf.row_indices[j + gap] = key_idx;
        }
    }

    return EXEC_OK;
}

